// The supported models and their prices (docs/llm.md, "Supported models, prices and the config form"): the types of
// the list (models, their providers' regions, prices), the names of providers and families, and the lookups everything
// else uses. Which pairs of provider and family the app supports is the adapters' business (adapters.ts). The list itself
// is a value of type ModelList (modelList.ts): generated by a script at release time, a mock until then, and a small
// list of their own in tests. Every lookup takes the list as its first argument, so any list can be plugged in.

import type { Effort } from "./types.ts";
import type { Price } from "./prices.ts";
import { supportedFamilies } from "./adapters.ts";

// Providers are platforms (decided 2026-11-05); "fake" ships with the app, "fake-dev" is for development (fake.ts).
export type Provider = "anthropic" | "bedrock" | "ai-studio" | "vertex" | "fake" | "fake-dev";
export const PROVIDERS: Provider[] = ["anthropic", "bedrock", "ai-studio", "vertex", "fake", "fake-dev"];

// As people call them: in the UI and in the default config names.
export const PROVIDER_NAMES: Record<Provider, string> = {
  anthropic: "Anthropic",
  bedrock: "Bedrock",
  "ai-studio": "AI Studio",
  vertex: "Vertex AI",
  fake: "Fake",
  "fake-dev": "Fake (dev)",
};

export type Family = "claude" | "gemini" | "fake";
export const FAMILY_NAMES: Record<Family, string> = {
  claude: "Claude",
  gemini: "Gemini",
  fake: "Fake",
};

// The effort levels a family offers, besides the model's default (a config's effort null).
export const EFFORTS: Record<Family, Effort[]> = {
  claude: ["low", "medium", "high", "xhigh", "max"],
  gemini: ["low", "medium", "high"],
  fake: ["low", "medium", "high", "xhigh", "max"],
};

// Bedrock's routing, in AWS's terms: global, within the region's geography (an inference profile: EU, US, JP, AU),
// or in the region only. Empty (null) for every other provider.
export type Routing = "global" | "geographic" | "in-region";

// Where a request goes: the region ("" for providers without regions; Vertex AI's location as Vertex spells it) and,
// on Bedrock, the routing.
export type Place = { region: string; routing: Routing | null };

// A region a provider has, and on Bedrock the routings it offers and its geography (for geographic routing: EU, US,
// JP, AU). Part of the list, collected with the models and prices: a model the user adds is offered its provider's
// regions; a listed model's places come from its prices.
export type RegionEntry = {
  provider: Provider;
  region: string;
  routings: Routing[] | null;
  geography?: string;
};

// Every place a provider offers in the list, in the list's order.
export function placesOfProvider(list: ModelList, provider: Provider): Place[] {
  return list.regions
    .filter((r) => r.provider === provider)
    .flatMap((r) => (r.routings ?? [null]).map((routing) => ({ region: r.region, routing })));
}

// One model, whatever the provider.
export type ModelEntry = {
  id: string; // stable across versions of the list: configs refer to it
  name: string; // for people: "Claude Opus 5.5"
  family: Family;
  strings: Partial<Record<Provider, string>>; // the model string as each provider spells it; missing: not offered
  retired?: true; // left the list: kept so that what refers to it still shows, never used for new calls
};

export type PriceEntry = Place & {
  model: string; // a ModelEntry's id
  provider: Provider;
  price: Price; // US dollars per million tokens
};

export type ModelList = {
  asOf: string; // when the list was collected (the About page's "prices as of")
  mock?: true; // a stand-in, not the providers' data
  models: ModelEntry[];
  regions: RegionEntry[];
  prices: PriceEntry[];
};

export function samePlace(a: Place, b: Place): boolean {
  return a.region === b.region && (a.routing ?? null) === (b.routing ?? null);
}

export function modelById(list: ModelList, id: string): ModelEntry | null {
  return list.models.find((m) => m.id === id) ?? null;
}

// The model string a listed model has on a provider, or null where the provider doesn't offer it.
export function modelString(list: ModelList, id: string, provider: Provider): string | null {
  return modelById(list, id)?.strings[provider] ?? null;
}

// The listed model a provider spells this way, if any: a config the user added becomes a listed one when a new list
// has its string (docs/llm.md, "Configs").
export function modelByString(list: ModelList, provider: Provider, string: string): ModelEntry | null {
  return list.models.find((m) => m.strings[provider] === string) ?? null;
}

// A listed model's price on a provider at a place, or null where the list has none.
export function listedPrice(list: ModelList, model: string, provider: Provider, place: Place): Price | null {
  return list.prices.find((p) => p.model === model && p.provider === provider && samePlace(p, place))?.price ?? null;
}

// The places where a listed model has a price on a provider (the region picker for a listed model).
export function placesOf(list: ModelList, model: string, provider: Provider): Place[] {
  return list.prices
    .filter((p) => p.model === model && p.provider === provider)
    .map(({ region, routing }) => ({ region, routing }));
}

// The models a provider offers with a price, at a place or anywhere (the model picker), retired ones left out.
export function modelsOf(list: ModelList, provider: Provider, place?: Place): ModelEntry[] {
  return list.models.filter(
    (m) =>
      !m.retired &&
      m.strings[provider] !== undefined &&
      list.prices.some((p) => p.model === m.id && p.provider === provider && (!place || samePlace(p, place))),
  );
}

// A config's model: listed (the list gives its string and family) or added by the user (its own string and family).
export type ConfigModel = { modelId: string } | { modelString: string; family: Family };

// How a config is priced (docs/llm.md, "Configs"): from the list, as its own model or as the reference's; free (the
// free-tier mark); or unpriced.
export type Pricing = { kind: "list"; reference: string | null } | { kind: "free" } | { kind: "unpriced" };

export type PricedConfig = {
  provider: Provider;
  model: ConfigModel;
  place: Place;
  pricing: Pricing;
};

// What the model is, for the adapter and the name: its string on the provider, its family, its name for people (none
// for a model the user added), and whether it is retired. Null for a listed model the provider doesn't offer, or one
// missing from the list.
export type ResolvedModel = {
  string: string;
  family: Family;
  name: string | null;
  retired: boolean;
};

export function resolveModel(list: ModelList, provider: Provider, model: ConfigModel): ResolvedModel | null {
  if ("modelString" in model)
    return {
      string: model.modelString,
      family: model.family,
      name: null,
      retired: false,
    };
  const entry = modelById(list, model.modelId);
  const string = entry?.strings[provider];
  if (!entry || string === undefined) return null;
  return {
    string,
    family: entry.family,
    name: entry.name,
    retired: entry.retired ?? false,
  };
}

// What a config's calls cost: a price (from the list, perhaps borrowed from the reference model), free, unpriced, or
// missing (priced from the list, but the list has no price there, so the call can't be counted).
export type ConfigPrice =
  | { kind: "priced"; price: Price; borrowedFrom: string | null }
  | { kind: "free" }
  | { kind: "unpriced" }
  | { kind: "missing" };

export function priceOfConfig(list: ModelList, config: PricedConfig): ConfigPrice {
  const { pricing } = config;
  if (pricing.kind === "free" || pricing.kind === "unpriced") return { kind: pricing.kind };
  const own = "modelId" in config.model ? config.model.modelId : null;
  const from = pricing.reference ?? own;
  const price = from === null ? null : listedPrice(list, from, config.provider, config.place);
  if (!price) return { kind: "missing" };
  return {
    kind: "priced",
    price,
    borrowedFrom: pricing.reference !== null && pricing.reference !== own ? pricing.reference : null,
  };
}

// A config's default name before numbering (docs/llm.md, "Configs"): "Claude Opus 5.5 (Bedrock) · high". A model the
// user added shows its string; the effort is left out where it is the model's default.
export function configBaseName(list: ModelList, provider: Provider, model: ConfigModel, effort: Effort | null): string {
  const resolved = resolveModel(list, provider, model);
  const name = resolved?.name ?? resolved?.string ?? ("modelId" in model ? model.modelId : model.modelString);
  return `${name} (${PROVIDER_NAMES[provider]})${effort ? ` · ${effort}` : ""}`;
}

// What is wrong with a list, in words: for the tests, and for the script's report before a release.
export function listProblems(list: ModelList): string[] {
  const problems: string[] = [];
  const ids = new Set<string>();
  for (const m of list.models) {
    if (ids.has(m.id)) problems.push(`Model ${m.id} is listed twice.`);
    ids.add(m.id);
    for (const provider of Object.keys(m.strings) as Provider[]) {
      if (!supportedFamilies(provider).includes(m.family))
        problems.push(
          `Model ${m.id}: the app doesn't support ${FAMILY_NAMES[m.family]} on ${PROVIDER_NAMES[provider]}.`,
        );
    }
  }
  for (const provider of PROVIDERS) {
    const seen = new Map<string, string>();
    for (const m of list.models) {
      const string = m.strings[provider];
      if (string === undefined) continue;
      const other = seen.get(string);
      if (other)
        problems.push(`Models ${other} and ${m.id} have the same string on ${PROVIDER_NAMES[provider]}: ${string}.`);
      seen.set(string, m.id);
    }
  }
  const regions = new Set<string>();
  for (const r of list.regions) {
    const where = `Region ${r.region || '""'} on ${PROVIDER_NAMES[r.provider]}`;
    const key = JSON.stringify([r.provider, r.region]);
    if (regions.has(key)) problems.push(`${where} is listed twice.`);
    regions.add(key);
    if ((r.routings !== null) !== (r.provider === "bedrock"))
      problems.push(
        r.routings === null ? `${where} has no routings.` : `${where} has routings, which only Bedrock has.`,
      );
    if (r.routings?.includes("geographic") && !r.geography)
      problems.push(`${where} routes geographically, but has no geography.`);
  }
  const keys = new Set<string>();
  for (const p of list.prices) {
    const where = `${p.model} on ${PROVIDER_NAMES[p.provider]}${p.region ? ` in ${p.region}` : ""}${p.routing ? ` (${p.routing})` : ""}`;
    const key = JSON.stringify([p.model, p.provider, p.region, p.routing]);
    if (keys.has(key)) problems.push(`Two prices for ${where}.`);
    keys.add(key);
    const model = modelById(list, p.model);
    if (!model) problems.push(`A price for ${where}, a model not in the list.`);
    else if (model.strings[p.provider] === undefined)
      problems.push(`A price for ${where}, but the model has no string there.`);
    if (!placesOfProvider(list, p.provider).some((place) => samePlace(place, p)))
      problems.push(`A price for ${where}, a place not in the list's regions.`);
    const values = [p.price.input, p.price.output, p.price.cacheRead, p.price.cacheWrite];
    if (values.some((v) => !Number.isFinite(v) || v < 0))
      problems.push(`A price for ${where} isn't a number of dollars.`);
  }
  for (const m of list.models) {
    for (const provider of Object.keys(m.strings) as Provider[]) {
      if (!m.retired && !list.prices.some((p) => p.model === m.id && p.provider === provider)) {
        problems.push(`Model ${m.id} has a string on ${PROVIDER_NAMES[provider]} but no price there.`);
      }
    }
  }
  return problems;
}
